<?php
require_once '../../config/auth.php'; require_once '../../config/database.php'; requireRole('admin');
$years=$pdo->query('SELECT id,tahun_ajaran FROM academic_years ORDER BY tanggal_mulai DESC')->fetchAll(PDO::FETCH_ASSOC); $yearId=(int)($_GET['academic_year_id']??0);
$sql="SELECT om.*,s.nama_lengkap,op.nama_jabatan,ay.tahun_ajaran,COALESCE(ch.nama_kelas,c.nama_kelas) nama_kelas,COALESCE(ch.jurusan,c.jurusan) jurusan FROM osis_members om INNER JOIN students s ON s.id=om.student_id INNER JOIN osis_positions op ON op.id=om.position_id INNER JOIN academic_years ay ON ay.id=om.academic_year_id LEFT JOIN student_class_history sch ON sch.student_id=om.student_id AND sch.academic_year_id=om.academic_year_id LEFT JOIN classes ch ON ch.id=sch.class_id LEFT JOIN classes c ON c.id=s.kelas_id WHERE om.status IN ('nonaktif','keluar','lulus')"; $params=[]; if($yearId){$sql.=' AND om.academic_year_id=?';$params[]=$yearId;} $sql.=' ORDER BY ay.tanggal_mulai DESC, om.tanggal_selesai DESC, s.nama_lengkap';$stmt=$pdo->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll(PDO::FETCH_ASSOC);
$pageTitle='Riwayat Anggota OSIS';require_once '../../includes/header.php';require_once '../../includes/sidebar.php'; ?>
<main class="main-content"><?php require_once '../../includes/navbar.php'; ?><section class="dashboard-container"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2>Riwayat Anggota OSIS</h2><p class="text-muted">Arsip anggota OSIS tahun lalu atau anggota yang sudah nonaktif, keluar, dan lulus.</p></div><a href="index.php" class="btn btn-primary">Anggota OSIS Aktif</a></div><form method="get" class="mb-3"><select class="form-select" style="max-width:280px" name="academic_year_id" onchange="this.form.submit()"><option value="">Semua tahun ajaran</option><?php foreach($years as $year): ?><option value="<?= (int)$year['id'] ?>" <?= $yearId===(int)$year['id']?'selected':'' ?>><?= htmlspecialchars($year['tahun_ajaran']) ?></option><?php endforeach ?></select></form><div class="card shadow-sm border-0"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Nama Siswa</th><th>Kelas / Jurusan</th><th>Jabatan</th><th>Tahun Ajaran</th><th>Mulai</th><th>Berhenti</th><th>Cetak</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><strong><?= htmlspecialchars($row['nama_lengkap']) ?></strong></td><td><?= htmlspecialchars($row['nama_kelas']?:'-') ?><small class="d-block text-muted"><?= htmlspecialchars($row['jurusan']?:'-') ?></small></td><td><?= htmlspecialchars($row['nama_jabatan']) ?></td><td><?= htmlspecialchars($row['tahun_ajaran']) ?></td><td><?= htmlspecialchars($row['tanggal_mulai']) ?></td><td><?= htmlspecialchars($row['tanggal_selesai']?:'-') ?></td><td><a href="cetak_sertifikat.php?id=<?= (int)$row['id'] ?>" class="btn btn-sm btn-outline-primary"><i class="bi bi-printer"></i> Sertifikat</a></td><td><span class="badge bg-secondary"><?= htmlspecialchars(ucfirst($row['status'])) ?></span></td></tr><?php endforeach;if(!$rows): ?><tr><td colspan="8" class="text-center text-muted py-4">Belum ada riwayat anggota OSIS.</td></tr><?php endif ?></tbody></table></div></div></section></main><?php require_once '../../includes/footer.php'; ?>
